// План specs/addresses.md 3.5–3.6 (кейс AD-09). Admin, компания «test». Только просмотр: превью — окно, JobDetail не открываем.
import { test, expect, Page } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from './address-helpers';
import { expectNoBrokenUnitFormat, expectUnitRightAfterStreet, pickAddress, textOf } from './address-display-helpers';

test.use({ storageState: ADMIN_STATE });

async function checkJobRowAndPreview(page: Page, job: string, status: string, street: string, expected: RegExp) {
  await setEnglish(page);
  await page.goto('/jobs');
  await expect(page.locator('main')).toContainText('JOB-00');
  await page.getByRole('tab', { name: status, exact: true }).or(page.getByRole('button', { name: status, exact: true })).first().click();

  const row = page.locator('tr', { hasText: job }).first();
  const rowText = await textOf(row, expected);
  expectUnitRightAfterStreet(pickAddress(rowText, street), `Jobs, строка ${job}`);
  expectNoBrokenUnitFormat(rowText, `Jobs, строка ${job}`);

  await row.getByTitle('Preview').click();
  const dialog = page.getByRole('dialog').last();
  await expect(dialog).toContainText(job);
  const dlgText = await textOf(dialog, expected);
  expectUnitRightAfterStreet(pickAddress(dlgText, street), `Jobs, превью ${job}`);
  expectNoBrokenUnitFormat(dlgText, `Jobs, превью ${job}`);
}

test.describe('Адрес: Unit в списке Jobs и в превью (#b2f74544)', () => {
  test('Jobs: JOB-0011 shows "Unit 1234" right after the street in the row and in the preview #b2f74544 @desktop @prod-safe', async ({ page }) => {
    // JOB-0011 виден только с фильтром Completed.
    await checkJobRowAndPreview(page, 'JOB-0011', 'Completed', '2221 NW Federal Hwy', /2221 NW Federal Hwy, Unit 1234, Stuart, FL 34994, USA/);
  });

  test('Jobs: JOB-0047 shows "#12" as typed, right after the street in the row and in the preview #b2f74544 @desktop @prod-safe', async ({ page }) => {
    await checkJobRowAndPreview(page, 'JOB-0047', 'Submitted', '2221 Northwest Federal Highway', /2221 Northwest Federal Highway, #12, Stuart, Florida/);
  });
});
